/* ==========================================================================
   SECTION 260
   Operational Decision Self-Test
   ========================================================================== */

/**
 * Run operational-decision utility checks.
 *
 * @param {Object} [options]
 * @param {boolean} [options.throwOnFailure=false]
 * @returns {Object}
 */
runOperationalDecisionSelfTest(
    options = {}
) {
    const {
        throwOnFailure = false
    } = options;

    const checks = [];

    const addCheck = (
        name,
        passed,
        actual = null,
        expected = null
    ) => {
        checks.push({
            name,
            passed: Boolean(passed),
            actual,
            expected
        });
    };

    const baseTimestamp =
        Date.UTC(
            2026,
            6,
            20,
            10,
            0,
            0
        );

    const severeInput = {
        targetId: 'jeddah',
        targetNameAr: 'جدة',
        targetNameEn: 'Jeddah',
        arrivalMinutes: 18,
        confidence: 88,
        riskScore: 82,
        rainProbability: 90,
        intensity: 78,
        floodRisk: 72,
        lightningRisk: 65,
        uncertaintyMinutes: 6,
        timestamp:
            baseTimestamp
    };

    const urgency =
        this.calculateArrivalUrgency(
            severeInput
        );

    addCheck(
        'arrival_urgency',
        urgency.score >= 70,
        urgency.score,
        '>=70'
    );

    const warning =
        this.resolveOperationalWarningLevel(
            severeInput
        );

    addCheck(
        'warning_resolution',
        warning.warningCode >= 3,
        warning.warningCode,
        '>=3'
    );

    const decision =
        this.generateFinalOperationalDecision(
            severeInput,
            [],
            {
                quietHoursEnabled: false
            }
        );

    addCheck(
        'notification_allowed',
        decision.shouldNotify ===
        true,
        decision.shouldNotify,
        true
    );

    const history = [
        {
            ...decision.alertRecord,
            timestamp:
                baseTimestamp
        }
    ];

    const duplicateDecision =
        this.generateFinalOperationalDecision(
            {
                ...severeInput,
                timestamp:
                    baseTimestamp +
                    5 *
                    60000
            },
            history,
            {
                quietHoursEnabled: false
            }
        );

    addCheck(
        'duplicate_suppression',
        duplicateDecision
            .shouldNotify ===
        false,
        duplicateDecision
            .shouldNotify,
        false
    );

    const escalatedInput = {
        ...severeInput,
        arrivalMinutes: 8,
        riskScore: 95,
        floodRisk: 90,
        timestamp:
            baseTimestamp +
            8 *
            60000
    };

    const escalationDecision =
        this.generateFinalOperationalDecision(
            escalatedInput,
            history,
            {
                quietHoursEnabled: false
            }
        );

    addCheck(
        'escalation_bypass',
        escalationDecision
            .shouldNotify ===
        true &&
        escalationDecision
            .shouldEscalate ===
        true,
        {
            shouldNotify:
                escalationDecision
                    .shouldNotify,
            shouldEscalate:
                escalationDecision
                    .shouldEscalate
        },
        {
            shouldNotify: true,
            shouldEscalate: true
        }
    );

    const integrationPayload =
        this.generateOperationalIntegrationPayload(
            decision
        );

    addCheck(
        'integration_payload',
        integrationPayload.valid ===
        true &&
        integrationPayload
            .eventType ===
        'rain_arrival_operational_decision',
        integrationPayload
            .eventType,
        'rain_arrival_operational_decision'
    );

    const passed =
        checks.every(
            (check) => check.passed
        );

    const result = {
        passed,
        checks,
        timestamp:
            new Date().toISOString()
    };

    if (!passed && throwOnFailure) {
        const failedChecks =
            checks
                .filter(
                    (check) =>
                        !check.passed
                )
                .map(
                    (check) =>
                        check.name
                )
                .join(', ');

        throw new Error(
            `[RainGuard AI V32] Operational decision self-test failed: ${failedChecks}`
        );
    }

    return result;
}


