/**
 * Resolve performance and caching configuration.
 *
 * @param {Object} [options]
 * @returns {Object}
 */
resolvePerformanceConfiguration(
    options = {}
) {
    return {
        cacheEnabled:
            options.cacheEnabled !==
            false,

        predictionCacheEnabled:
            options.predictionCacheEnabled !==
            false,

        sourceCacheEnabled:
            options.sourceCacheEnabled !==
            false,

        memoizationEnabled:
            options.memoizationEnabled !==
            false,

        requestDeduplicationEnabled:
            options.requestDeduplicationEnabled !==
            false,

        concurrentLockEnabled:
            options.concurrentLockEnabled !==
            false,

        predictionCacheTtlMs:
            Math.max(
                0,
                Number(
                    options.predictionCacheTtlMs
                ) ||
                2 *
                60 *
                1000
            ),

        sourceCacheTtlMs:
            Math.max(
                0,
                Number(
                    options.sourceCacheTtlMs
                ) ||
                5 *
                60 *
                1000
            ),

        memoizationTtlMs:
            Math.max(
                0,
                Number(
                    options.memoizationTtlMs
                ) ||
                10 *
                60 *
                1000
            ),

        requestDeduplicationTtlMs:
            Math.max(
                0,
                Number(
                    options.requestDeduplicationTtlMs
                ) ||
                30 *
                1000
            ),

        lockTimeoutMs:
            Math.max(
                100,
                Number(
                    options.lockTimeoutMs
                ) ||
                30 *
                1000
            ),

        maximumPredictionCacheEntries:
            Math.max(
                1,
                Number(
                    options.maximumPredictionCacheEntries
                ) || 100
            ),

        maximumSourceCacheEntries:
            Math.max(
                1,
                Number(
                    options.maximumSourceCacheEntries
                ) || 250
            ),

        maximumMemoizationEntries:
            Math.max(
                1,
                Number(
                    options.maximumMemoizationEntries
                ) || 500
            ),

        maximumPerformanceSamples:
            Math.max(
                10,
                Number(
                    options.maximumPerformanceSamples
                ) || 500
            ),

        cacheCleanupIntervalMs:
            Math.max(
                1000,
                Number(
                    options.cacheCleanupIntervalMs
                ) ||
                5 *
                60 *
                1000
            ),

        slowExecutionThresholdMs:
            Math.max(
                1,
                Number(
                    options.slowExecutionThresholdMs
                ) || 1000
            ),

        debounceDelayMs:
            Math.max(
                0,
                Number(
                    options.debounceDelayMs
                ) || 250
            ),

        throttleIntervalMs:
            Math.max(
                0,
                Number(
                    options.throttleIntervalMs
                ) || 1000
            ),

        cacheNullValues:
            options.cacheNullValues ===
            true,

        cloneCachedValues:
            options.cloneCachedValues !==
            false,

        trackCacheMetrics:
            options.trackCacheMetrics !==
            false
    };
}


