/**
 * Resolve security, validation, and integrity configuration.
 *
 * @param {Object} [options]
 * @returns {Object}
 */
resolveSecurityConfiguration(
    options = {}
) {
    return {
        securityEnabled:
            options.securityEnabled !==
            false,

        inputSanitizationEnabled:
            options.inputSanitizationEnabled !==
            false,

        schemaValidationEnabled:
            options.schemaValidationEnabled !==
            false,

        prototypePollutionProtectionEnabled:
            options.prototypePollutionProtectionEnabled !==
            false,

        trustedSourceValidationEnabled:
            options.trustedSourceValidationEnabled !==
            false,

        integrityHashEnabled:
            options.integrityHashEnabled !==
            false,

        strictSecurityMode:
            options.strictSecurityMode ===
            true,

        maximumPayloadDepth:
            Math.max(
                1,
                Number(
                    options.maximumPayloadDepth
                ) || 20
            ),

        maximumPayloadKeys:
            Math.max(
                10,
                Number(
                    options.maximumPayloadKeys
                ) || 5000
            ),

        maximumArrayLength:
            Math.max(
                1,
                Number(
                    options.maximumArrayLength
                ) || 2000
            ),

        maximumStringLength:
            Math.max(
                1,
                Number(
                    options.maximumStringLength
                ) || 10000
            ),

        maximumPayloadSizeBytes:
            Math.max(
                1024,
                Number(
                    options.maximumPayloadSizeBytes
                ) ||
                2 *
                1024 *
                1024
            ),

        maximumObservationCount:
            Math.max(
                1,
                Number(
                    options.maximumSecureObservationCount
                ) || 500
            ),

        maximumCityCount:
            Math.max(
                1,
                Number(
                    options.maximumSecureCityCount
                ) || 2000
            ),

        maximumTrackPointCount:
            Math.max(
                1,
                Number(
                    options.maximumSecureTrackPointCount
                ) || 1000
            ),

        minimumValidTimestamp:
            Number(
                options.minimumValidTimestamp
            ) ||
            Date.UTC(
                2000,
                0,
                1
            ),

        maximumFutureTimestampOffsetMs:
            Math.max(
                0,
                Number(
                    options.maximumFutureTimestampOffsetMs
                ) ||
                7 *
                24 *
                60 *
                60 *
                1000
            ),

        maximumPastTimestampAgeMs:
            Math.max(
                0,
                Number(
                    options.maximumPastTimestampAgeMs
                ) ||
                30 *
                24 *
                60 *
                60 *
                1000
            ),

        coordinatePrecision:
            Math.max(
                0,
                Math.min(
                    10,
                    Number(
                        options.coordinatePrecision
                    ) || 6
                )
            ),

        maximumSpeedKmh:
            Math.max(
                1,
                Number(
                    options.maximumSecureSpeedKmh
                ) || 300
            ),

        maximumRainIntensity:
            Math.max(
                1,
                Number(
                    options.maximumRainIntensity
                ) || 1000
            ),

        allowUnknownSources:
            options.allowUnknownSources ===
            true,

        allowUnknownFields:
            options.allowUnknownFields !==
            false,

        removeInvalidFields:
            options.removeInvalidFields !==
            false,

        rejectOversizedPayloads:
            options.rejectOversizedPayloads !==
            false,

        trimStrings:
            options.trimStrings !==
            false,

        normalizeUnicode:
            options.normalizeUnicode !==
            false,

        allowHtmlStrings:
            options.allowHtmlStrings ===
            true,

        integrityAlgorithm:
            String(
                options.integrityAlgorithm ??
                'rg32-fnv1a-64'
            )
    };
}


